#include "spell.h"
#include "editor.h"
#include "services.h"
#include "markdown.h"
#include <QContextMenuEvent>
namespace Mojian {
Speller &Speller::instance(){static Speller value;return value;}
Speller::Speller(){for(const auto &name:{"hunspell-1.7","libhunspell-1.7.so.0","hunspell"}){library.setFileName(name);if(library.load())break;}if(!library.isLoaded())return;auto create=reinterpret_cast<Create>(library.resolve("Hunspell_create"));destroy=reinterpret_cast<Destroy>(library.resolve("Hunspell_destroy"));spell=reinterpret_cast<Spell>(library.resolve("Hunspell_spell"));suggest=reinterpret_cast<Suggest>(library.resolve("Hunspell_suggest"));freeList=reinterpret_cast<FreeList>(library.resolve("Hunspell_free_list"));if(!create||!destroy||!spell||!suggest||!freeList)return;for(auto extension:{"aff","dic"}){QFile resource(":/mojian/dictionaries/en_US."+QString(extension));if(!resource.open(QIODevice::ReadOnly))return;QFile output(dictionary.filePath("en_US."+QString(extension)));if(!output.open(QIODevice::WriteOnly)||output.write(resource.readAll())<0)return;}auto aff=dictionary.filePath("en_US.aff").toUtf8(),dic=dictionary.filePath("en_US.dic").toUtf8();handle=create(aff.constData(),dic.constData());}
Speller::~Speller(){if(handle&&destroy)destroy(handle);}
bool Speller::available()const{return handle!=nullptr;}
bool Speller::correct(const QString &word){if(!handle||QSettings().value("spellWords").toStringList().contains(word,Qt::CaseInsensitive))return true;if(cache.contains(word))return cache[word];if(cache.size()>20000)cache.clear();auto bytes=word.toUtf8();bool result=spell(handle,bytes.constData())!=0;cache[word]=result;return result;}
QStringList Speller::suggestions(const QString &word){QStringList result;if(!handle)return result;char **values=nullptr;auto bytes=word.toUtf8();int count=suggest(handle,&values,bytes.constData());for(int i=0;i<std::min(count,8);++i)result<<QString::fromUtf8(values[i]);if(values)freeList(handle,&values,count);return result;}
void Speller::remember(const QString &word){auto values=QSettings().value("spellWords").toStringList();if(!values.contains(word))values<<word;QSettings().setValue("spellWords",values);cache.remove(word);}
void Editor::contextMenuEvent(QContextMenuEvent *event){auto menu=createStandardContextMenu();auto cursor=cursorForPosition(event->pos());cursor.select(QTextCursor::WordUnderCursor);QString word=cursor.selectedText();if(QSettings().value("spellCheck",false).toBool()&&!word.isEmpty()&&!Speller::instance().correct(word)){auto separator=menu->insertSeparator(menu->actions().isEmpty()?nullptr:menu->actions().first());for(auto suggestion:Speller::instance().suggestions(word)){auto action=new QAction(suggestion,menu);menu->insertAction(separator,action);connect(action,&QAction::triggered,this,[cursor,suggestion]()mutable{cursor.insertText(suggestion);});}auto remember=new QAction("加入个人词典",menu);menu->insertAction(separator,remember);connect(remember,&QAction::triggered,this,[this,word]{Speller::instance().remember(word);highlighter->rehighlight();});}auto snapshot=Markdown::parse(toPlainText(),QSettings().value("dialect","extended").toString());auto owner=qobject_cast<Window *>(window());for(auto node:Markdown::descendants(snapshot->root))if(cursor.position()>=node.start&&cursor.position()<=node.end){if(node.type=="link"){QUrl url(node.url);if(QStringList{"http","https","mailto","file"}.contains(url.scheme())){auto open=menu->addAction("打开链接");connect(open,&QAction::triggered,this,[url]{QDesktopServices::openUrl(url);});auto copy=menu->addAction("复制链接地址");connect(copy,&QAction::triggered,this,[url]{QApplication::clipboard()->setText(url.toString());});}}if(node.type=="image"&&owner){auto action=menu->addAction("图片设置…");connect(action,&QAction::triggered,this,[this,cursor,owner]{setTextCursor(cursor);setFocus();owner->services->inspectImage();});}if(node.type=="code_block"&&!node.info.startsWith("mojian-")){auto action=menu->addAction("修改代码语言…");connect(action,&QAction::triggered,this,[this,node]{auto block=document()->findBlock(node.start);auto match=QRegularExpression("^(.*?)(`{3,}|~{3,})(.*)$").match(block.text());if(!match.hasMatch())return;bool ok;QString language=QInputDialog::getText(this,"代码语言","语言标签",QLineEdit::Normal,node.info,&ok);if(ok&&QRegularExpression("^[A-Za-z0-9_+.-]*$").match(language).hasMatch()){QTextCursor cursor(block);cursor.movePosition(QTextCursor::EndOfBlock,QTextCursor::KeepAnchor);cursor.insertText(match.captured(1)+match.captured(2)+language);}});}}
    menu->exec(event->globalPos());delete menu;}
}
